const start = Date.now();
const body = $('Validate Input1').first().json.body;

const test_type = body.test_type || '';
const patient   = body.patient_name || 'Невідомий';

// ── Нормалізація відповідей ──────────────────────────────────────────────────
let raw = body.answers || [];
let answers;
if (!Array.isArray(raw) && typeof raw === 'object') {
  answers = Object.keys(raw).sort((a,b)=>parseInt(a)-parseInt(b)).map(k=>parseInt(raw[k])||0);
} else {
  answers = raw.map(a=>parseInt(a)||0);
}

function resolveType(declared, ans) {
  if (['pcl5','minmult','schmishek'].includes(declared)) return declared;
  if (ans.length <= 20) return 'pcl5';
  if (ans.length <= 71) return 'minmult';
  return 'schmishek';
}
const resolved_type = resolveType(test_type, answers);

// ── Сувора перевірка відповідей: жодних мовчазних підстановок нулів ─────────
// Порожнє, нечислове або недопустиме значення = помилка (токен звільняється, пацієнт отримує 500 і може повторити).
const ALLOWED_VALUES = { pcl5: [0, 1, 2, 3, 4], minmult: [0, 1], schmishek: [0, 1] };
const rawList = Array.isArray(raw)
  ? raw
  : Object.keys(raw).sort((a, b) => parseInt(a) - parseInt(b)).map(k => raw[k]);
const isValidAnswer = (v) =>
  (typeof v === 'number' || (typeof v === 'string' && /^\d+$/.test(v))) &&
  ALLOWED_VALUES[resolved_type].includes(Number(v));
if (!rawList.every(isValidAnswer)) {
  throw new Error('Invalid answer value for ' + resolved_type + ' (empty, non-numeric or out of range)');
}

// ── PCL-5 (20 питань, шкала 0-4) ────────────────────────────────────────────
// Кластери DSM-5:
// B (1-5)  — Вторгнення
// C (6-7)  — Уникнення
// D (8-14) — Негативні зміни когніцій/настрою
// E (15-20)— Гіперзбудження
function score_pcl5(ans) {
  if (ans.length !== 20) throw new Error('PCL-5: expected 20 answers, got ' + ans.length);
  const a = ans.map(v => Math.min(4, Math.max(0, v)));
  const sum = (arr) => arr.reduce((s, v) => s + v, 0);
  const pos = (arr) => arr.filter(v => v >= 2).length;
  const cl = { B: a.slice(0,5), C: a.slice(5,7), D: a.slice(7,14), E: a.slice(14,20) };
  const clusters = { B: sum(cl.B), C: sum(cl.C), D: sum(cl.D), E: sum(cl.E) };
  const total = sum(a);
  // DSM-5 provisional: >=1 B, >=1 C, >=2 D, >=2 E при оцінці >=2 (правило за пам'яттю, не перевірено)
  const dsm_provisional = pos(cl.B)>=1 && pos(cl.C)>=1 && pos(cl.D)>=2 && pos(cl.E)>=2;
  const cutoff_met = total >= 33; // діапазон порога 31–33 (не перевірено)
  return {
    total,
    severity: 'pending',
    severity_ua: `Сума ${total}/80; поріг 31–33: ${cutoff_met ? 'досягнуто' : 'не досягнуто'}; DSM-5 (попередньо): ${dsm_provisional ? 'так' : 'ні'}`,
    ptsd_probable: dsm_provisional || cutoff_met,
    details: { clusters, dsm_provisional, cutoff_met },
    subscales: {
      'B_Вторгнення': clusters.B, 'C_Уникнення': clusters.C,
      'D_Когніції/настрій': clusters.D, 'E_Збудження': clusters.E,
    },
  };
}

// ── Міні-Мульт (Kincannon 1968; Зайцев, Козюля) — 71 питання, відповіді Так(1)/Ні(0) ──
// Ключ звірено по всіх 11 шкалах з другим джерелом (psychic.at.ua, Зайцев і Козюля);
// з оригіналом Козюля В.Г. (1994) НЕ звірено.
// Нумерація питань збігається з текстом 71 питання цього джерела.
// У джерелі пункт 24 стоїть і в L, і в F (відповідь «Ні») — можлива помилка джерела, збережено як є.
// Бали Hs, Pd, Pt, Sc, Ma повертаються вже з поправкою на K; сирі бали — у details.subscales_raw.
// T-бали: T = 50 + 10·(X − M)/σ, норми M і σ за статтю з таблиці джерела (формула на сторінці — картинка, взято стандартну MMPI).
const MM_KEY = {
  L:  { no: [5,11,24,47,53], yes: [] },
  F:  { no: [22,24,61], yes: [9,12,15,19,30,38,48,49,58,59,64,71] },
  K:  { no: [11,23,31,33,34,36,40,41,43,51,56,61,65,67,69,70], yes: [] },
  'Hs_1_Іпохондрія':   { no: [1,2,6,37,45], yes: [9,18,26,32,44,46,55,62,63] },
  'D_2_Депресія':      { no: [1,3,6,11,28,37,40,42,60,65,71], yes: [9,13,17,18,22,25,36,44] },
  'Hy_3_Істерія':      { no: [1,2,3,11,23,28,29,31,33,35,37,40,41,43,45,50,56], yes: [9,13,18,26,44,46,55,57,62] },
  'Pd_4_Психопатія':   { no: [3,28,34,35,41,43,50,65], yes: [7,10,13,14,15,16,22,27,52,58,71] },
  'Pa_6_Параноя':      { no: [28,29,31,67], yes: [5,8,10,15,30,39,63,64,66,68] },
  'Pt_7_Психастенія':  { no: [2,3,42], yes: [5,8,13,17,22,25,27,36,44,51,57,66,68] },
  'Sc_8_Шизоїдність':  { no: [3,42], yes: [5,7,8,10,13,14,15,16,17,26,30,38,39,46,57,63,64,66] },
  'Ma_9_Гіпоманія':    { no: [43], yes: [4,7,8,21,29,34,38,39,54,57,60] },
};
// Поправка на K: частка K, що додається до шкали
const MM_K_COEF = { 'Hs_1_Іпохондрія': 0.5, 'Pd_4_Психопатія': 0.4, 'Pt_7_Психастенія': 1.0, 'Sc_8_Шизоїдність': 1.0, 'Ma_9_Гіпоманія': 0.2 };

// Pd: поправка 0,4К берётся из таблицы источника (Math.round расходится с ней при K=1 и K=3)
const MM_PD_TABLE = {0:0,1:1,2:1,3:2,4:2,5:2,6:2,7:3,8:3,9:4,10:4,11:4,12:5,13:5,14:6,15:6,16:6};
function mm_k_add(n, K) {
  if (n === 'Pd_4_Психопатія' && MM_PD_TABLE[K] !== undefined) return MM_PD_TABLE[K];
  return Math.round((MM_K_COEF[n] || 0) * K);
}

// ── T-бали (T = 50 + 10·(X − M)/σ), норми за статтю з таблиці джерела ──────────
// Х для Hs, Pd, Pt, Sc, Ma — бал уже з поправкою на K; L, F, K — сирі.
const MM_NORMS = {
  M: { L:[1.48,1.23], F:[3.1,2.3], K:[7.68,3.42],
       'Hs_1_Іпохондрія':[7.24,3], 'D_2_Депресія':[7.02,2.68], 'Hy_3_Істерія':[9.73,2.91],
       'Pd_4_Психопатія':[10.39,2.13], 'Pa_6_Параноя':[4.03,1.74], 'Pt_7_Психастенія':[13.57,2.51],
       'Sc_8_Шизоїдність':[13.68,2.83], 'Ma_9_Гіпоманія':[6.23,1.55] },
  F: { L:[1.51,1.19], F:[2.64,1.71], K:[7.72,2.64],
       'Hs_1_Іпохондрія':[8.47,2.92], 'D_2_Депресія':[7.96,3], 'Hy_3_Істерія':[11.53,3.38],
       'Pd_4_Психопатія':[9.76,1.9], 'Pa_6_Параноя':[4.77,2], 'Pt_7_Психастенія':[14.48,2.27],
       'Sc_8_Шизоїдність':[13.52,2.8], 'Ma_9_Гіпоманія':[6.35,1.91] },
};
function mm_t(sex, name, x) {
  const t = MM_NORMS[sex] && MM_NORMS[sex][name];
  return t ? Math.round(50 + 10 * (x - t[0]) / t[1]) : null;
}
const session_sex = (() => {
  try {
    const s = String($('DB: Check Session Status1').first().json.sex || '').trim().toUpperCase();
    return (s === 'M' || s === 'F') ? s : null;
  } catch (e) { return null; }
})();

function score_minmult(ans, sex) {
  if (ans.length !== 71) throw new Error('Mini-Mult: expected 71 answers, got ' + ans.length);
  const a = ans.slice(0, 71);
  const raw = {};
  for (const [name, key] of Object.entries(MM_KEY)) {
    let s = 0;
    for (const k of key.yes) if (k <= a.length && a[k-1] === 1) s++;
    for (const k of key.no)  if (k <= a.length && a[k-1] === 0) s++;
    raw[name] = s;
  }
  const K = raw.K;
  const clinical = Object.keys(MM_KEY).filter(n => !['L','F','K'].includes(n));
  const scales = {};
  const scales_raw = {};
  for (const n of clinical) { scales_raw[n] = raw[n]; scales[n] = raw[n] + mm_k_add(n, K); }
  const values = clinical.map(n => scales[n]);
  const maxVal = Math.max(...values);
  const total = values.reduce((s,v) => s+v, 0);
  const peak_scale = clinical[values.indexOf(maxVal)];
  const validity = { L: raw.L, F: raw.F, K };
  let t_scores = null, t_validity = null;
  if (sex) {
    t_scores = {}; for (const n of clinical) t_scores[n] = mm_t(sex, n, scales[n]);
    t_validity = { L: mm_t(sex, 'L', raw.L), F: mm_t(sex, 'F', raw.F), K: mm_t(sex, 'K', raw.K) };
  }
  return {
    total,
    severity: 'unknown',
    severity_ua: 'Т-бали не розраховано (див. шкали)',
    peak_scale,
    subscales: scales,
    validity,
    elevated_scales: [],
    details: { subscales: scales, subscales_raw: scales_raw, validity, peak_scale, k_corrected: true, sex: sex || null, ...(t_scores ? { t_scores, t_validity, t_formula: 'T = 50 + 10*(X - M)/sigma' } : {}) }
  };
}

// ── Шмішек — 88 питань, відповіді Так(1)/Ні(0), 10 шкал (Леонгард) ──────────────
// Питання взято з kipt.sumdu.edu.ua (опитувальник Леонгарда-Шмішека). Макс. на шкалу = 24.
// Розбіжності ключа з текстом джерела (збережено наш варіант за змістом питань):
//  • Педантизм: у джерелі (+) …39, 63, 80 і (−) 36; у нас (+) …36, 80, 83 і (−) 39;
//  • Демонстративність: у джерелі немає п. 44; Дистимія: у джерелі немає «Ні»-пунктів 31, 53, 65
//    (без них максимум нижчий за заявлені 24);
//  • Збудливість: у джерелі не вказано множник, прийнято ×3 (макс. 24).
const SCH_KEY = {
  'Демонстративність': { yes: [7,19,22,29,41,44,63,66,73,85,88], no: [51], mult: 2 },
  'Застрягання':       { yes: [2,15,24,34,37,56,68,78,81],       no: [12,46,59], mult: 2 },
  'Педантизм':         { yes: [4,14,17,26,36,48,58,61,70,80,83], no: [39], mult: 2 },
  'Збудливість':       { yes: [8,20,30,42,52,64,74,86],          no: [], mult: 3 },
  'Гіпертимія':        { yes: [1,11,23,33,45,55,67,77],          no: [], mult: 3 },
  'Дистимія':          { yes: [9,21,43,75,87],                   no: [31,53,65], mult: 3 },
  'Тривожність':       { yes: [16,27,38,49,60,71,82],            no: [5], mult: 3 },
  'Екзальтованість':   { yes: [10,32,54,76],                     no: [], mult: 6 },
  'Емотивність':       { yes: [3,13,35,47,57,69,79],             no: [25], mult: 3 },
  'Циклотимія':        { yes: [6,18,28,40,50,62,72,84],          no: [], mult: 3 },
};
// Джерела розходяться: ознака акцентуації >12 або >19 (15-19 = тенденція). Змінюйте тут.
const SCH_ACCENT_MIN = 20;
// Джерело: 15–19 балів — лише тенденція до акцентуації, >19 — акцентуація
const SCH_TENDENCY_MIN = 15;

function score_schmishek(ans) {
  if (ans.length !== 88) throw new Error('Schmishek: expected 88 answers, got ' + ans.length);
  const a = ans.slice(0, 88);
  const scales = {};
  for (const [name, key] of Object.entries(SCH_KEY)) {
    let s = 0;
    for (const k of key.yes) if (k <= a.length && a[k-1] === 1) s++;
    for (const k of key.no)  if (k <= a.length && a[k-1] === 0) s++;
    scales[name] = s * key.mult;
  }
  const entries = Object.entries(scales);
  const peak = [...entries].sort(([,x],[,y]) => y - x)[0];
  const total = entries.reduce((s,[,v]) => s+v, 0);
  const accentuated = entries.filter(([,v]) => v >= SCH_ACCENT_MIN).map(([k]) => k);

  let severity, severity_ua;
  if (accentuated.length === 0)     { severity='low';      severity_ua='В нормі'; }
  else if (accentuated.length <= 2) { severity='moderate'; severity_ua='Акцентуація'; }
  else if (accentuated.length <= 4) { severity='high';     severity_ua='Виражена'; }
  else                              { severity='severe';   severity_ua='Дуже виражена'; }

  const profile = Object.keys(SCH_KEY).map(name => ({
    name,
    score: scales[name],
    level: scales[name] >= SCH_ACCENT_MIN ? 'accentuation' : (scales[name] >= SCH_TENDENCY_MIN ? 'tendency' : 'normal')
  }));
  const tendency = profile.filter(p => p.level === 'tendency').map(p => p.name);
  return {
    total, severity, severity_ua,
    subscales: Object.fromEntries([...entries].sort(([,x],[,y]) => y - x)),
    accentuated_types: accentuated,
    peak_type: peak?.[0],
    peak_score: peak?.[1],
    details: { profile, accentuated_types: accentuated, tendency_types: tendency, thresholds: { accentuation: SCH_ACCENT_MIN, tendency: SCH_TENDENCY_MIN }, max_per_scale: 24 }
  };
}

// ── Запуск ───────────────────────────────────────────────────────────────────
const scorers    = { pcl5: score_pcl5, minmult: score_minmult, schmishek: score_schmishek };
const test_names = { pcl5:'PCL-5 (ПТСР)', minmult:'Міні-Мульт (MMPI)', schmishek:'Шмішек (акцентуації)' };

if (!scorers[resolved_type]) throw new Error('Unknown test_type: ' + resolved_type);

const result = scorers[resolved_type](answers, session_sex);
const scoring_time_ms = Date.now() - start;

return [{
  json: {
    ...body,
    answers,
    test_type:        resolved_type,
    test_name:        test_names[resolved_type],
    score:            result.total,
    severity:         result.severity,
    severity_ua:      result.severity_ua,
    subscales:        result.subscales,
    scoring_time_ms,
    // Поля специфічні для кожного тесту
    ...(result.ptsd_probable     !== undefined && { ptsd_probable:     result.ptsd_probable }),
    ...(result.peak_scale        !== undefined && { peak_scale:        result.peak_scale }),
    ...(result.elevated_scales   !== undefined && { elevated_scales:   result.elevated_scales }),
    ...(result.validity          !== undefined && { validity:          result.validity }),
    ...(result.accentuated_types !== undefined && { accentuated_types: result.accentuated_types }),
    ...(result.peak_type         !== undefined && { peak_type:         result.peak_type }),
    ...(result.peak_score        !== undefined && { peak_score:        result.peak_score }),
    ...(result.details           !== undefined && { details:           result.details }),
  }
}];
